"""Independently reread every selected count/ID and frozen PCA, before official fitting."""
from pathlib import Path
from datetime import datetime,timezone
import os,json,hashlib,gzip,gc
import numpy as np,pandas as pd,zarr
from scipy.sparse import csr_matrix,vstack
from scipy.io import mmread

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 R=Path(os.environ['PANCANCER_PREFLIGHT_ROOT']);AR=Path(os.environ['PANCANCER_ANNOTATION_ROOT']);V=Path(os.environ['PANCANCER_STATE_MODEL_OUTPUT_ROOT']);S=V/'state_after_DIALOGUE_inputs_20261016_v3';iv=json.loads((S/'inventory.json').read_text());assert iv['status']=='PREPARED_ALL14_STATE_AFTER_DIALOGUE_CONTEXT_INPUTS_NOT_MODELS';assert len(iv['contexts'])==14;F=R/'all_CM_state_native_input_preflight_20261014_v1';fi=json.loads((F/'inventory.json').read_text());U=F/'private_all_frozen_sample_node_units.tsv.gz';assert sha(U)==fi['private_unit_table_sha256'];u=pd.read_csv(U,sep='\t',keep_default_na=False);p=F/'private_canonical_row_selection.npz';assert sha(p)==fi['private_row_selection_sha256'];z=np.load(p);erows=z['global_rows'];eu=z['unit_index'];UC=AR/'20261010_uniform_expression_annotation_v1';contract=json.loads((UC/'input_contract.json').read_text());g=zarr.open_group(contract['core_zarr'],mode='r');x=g['X'];key=g['obs'].attrs['_index'];summary=[];maxdiff=0;total=0
 for ctx in iv['contexts']:
  root=S/ctx['relative_dir'];assert sha(root/'private_input_inventory.json')==ctx['input_inventory_sha256'];q=json.loads((root/'private_input_inventory.json').read_text())
  for name,h in q['files'].items():assert sha(root/name)==h
  parts=pd.read_csv(root/'private_block_library_partition.tsv',sep='\t',keep_default_na=False);assert parts.effective_resampling_block.is_unique and parts.sample_uid.is_unique;assert set(parts.partition)<=set(['discovery','holdout']);assert len(parts[parts.partition=='discovery'])>=20
  if ctx['mode']=='BLOCK_HOLDOUT':assert len(parts[parts.partition=='holdout'])>=10
  else:assert not parts.partition.eq('holdout').any()
  gt=pd.read_csv(UC/'by_gse'/q['gse_id']/'genes.tsv',sep='\t');genes=gt.gene.to_numpy(str);gcols=gt.core_column.to_numpy(int)
  for side in ['A','B']:
   matrices=[];metadata=[];pcs=[];lastgenes=None
   for partition in ['discovery','holdout']:
    prefix=root/('type'+side+'_'+partition);mp=Path(str(prefix)+'_metadata.tsv')
    if not mp.exists():continue
    md=pd.read_csv(mp,sep='\t',keep_default_na=False);mat=mmread(str(prefix)+'_tpm.mtx.gz').T.tocsr();gn=np.loadtxt(str(prefix)+'_genes.tsv',dtype=str,ndmin=1);pc=pd.read_csv(str(prefix)+'_PC.tsv',sep='\t',index_col=0);assert np.array_equal(pc.index.to_numpy(str),md.cell.to_numpy(str)) and pc.shape==(len(md),20) and mat.shape==(len(md),len(gn));assert md.partition.eq(partition).all() and md.cell.is_unique;assert md.groupby('block').size().between(20,100).all();assert set(md.block)==set(parts.loc[parts.partition.eq(partition),'effective_resampling_block']);where=np.searchsorted(erows,md.global_row.to_numpy(int));assert np.array_equal(erows[where],md.global_row.to_numpy(int)) and np.array_equal(eu[where],md.unit_index);um=u.iloc[md.unit_index.to_numpy(int)];assert um.subCluster.eq(q['endpoints'][0 if side=='A' else 1]).all() and um.gse_id.eq(q['gse_id']).all();assert np.array_equal(um.sample_uid.to_numpy(str),md.sample_uid.to_numpy(str));assert np.array_equal(np.asarray(g['obs'][key].get_orthogonal_selection((md.global_row.to_numpy(int),)).tolist(),dtype=str),md.cell.to_numpy(str));assert lastgenes is None or np.array_equal(lastgenes,gn);lastgenes=gn;matrices.append(mat);metadata.append(md);pcs.append(pc.to_numpy(float))
   md=pd.concat(metadata,ignore_index=True);mat=vstack(matrices,format='csr');pc=np.vstack(pcs);rr=md.global_row.to_numpy(int);order=np.argsort(rr);sortedrows=rr[order];rawparts=[];start=0
   while start<len(rr):
    end=min(start+250,len(rr),int(np.searchsorted(sortedrows,sortedrows[start]+3000,side='left')));take=sortedrows[start:end];lo=int(take[0]);hi=int(take[-1])+1;ip=np.asarray(x['indptr'][lo:hi+1],np.int64);a,b=int(ip[0]),int(ip[-1]);source=csr_matrix((x['data'][a:b],x['indices'][a:b],ip-a),shape=(hi-lo,contract['raw_shape'][1]))[take-lo].tocoo();assert np.isfinite(source.data).all() and (source.data>=0).all() and np.array_equal(source.data,np.floor(source.data));rawparts.append(csr_matrix((source.data,(source.row,source.col)),shape=source.shape));start=end
   raw=vstack(rawparts,format='csr')[np.argsort(order)];tot=np.asarray(raw.sum(1)).ravel();det=np.asarray((raw>0).sum(1)).ravel();train=md.partition.eq('discovery').to_numpy();local=raw[:,gcols];active=(np.asarray((local[train]>0).sum(axis=0)).ravel()/train.sum()>=.01)&~pd.Index(genes).str.match(r'^(MT-|RPL|RPS)');assert np.array_equal(genes[active],lastgenes),('GENE_AXIS_DIFFERENCE',q['context'],side);chosen=raw[:,pd.Series(gcols,index=genes).loc[lastgenes].to_numpy()].tocoo();expected=csr_matrix((np.log1p(chosen.data*10000/tot[chosen.row]),(chosen.row,chosen.col)),shape=chosen.shape);delta=expected-mat;err=float(np.max(np.abs(delta.data))) if delta.nnz else 0.;assert err<1e-10;maxdiff=max(maxdiff,err)
   frozen=dict(np.load(root/('type'+side+'_frozen_transform.npz'),allow_pickle=False));hvg=pd.Index(lastgenes).get_indexer(frozen['HVG_genes']);assert (hvg>=0).all();assert np.allclose(np.asarray(mat[train][:,hvg].mean(0)).ravel(),frozen['PCA_mean'],atol=1e-10);repc=(mat[:,hvg].toarray()-frozen['PCA_mean'])@frozen['PCA_components'].T;assert np.allclose(pc,repc,atol=1e-9,rtol=1e-8);qual=np.column_stack([np.log1p(tot),np.log1p(det)]);assert np.allclose(qual[train].mean(0),frozen['quality_mean'],atol=1e-10) and np.allclose(qual[train].std(0),frozen['quality_sd'],atol=1e-10);quality=(qual-frozen['quality_mean'])/frozen['quality_sd'];assert np.allclose(quality,md[['cellQ','geneQ']],atol=1e-10)
   summary.append(dict(context=q['context'],side=side,cells=len(md),genes=len(lastgenes),all_IDs_units_counts_logexpr_PCs_QC_pass=True,normalized_value_max_error=err));total+=len(md);del raw,local,mat,rawparts,expected,delta;gc.collect()
 O=V/'state_after_DIALOGUE_input_acceptance_20261016_v2';assert not O.exists();O.mkdir(mode=0o700);pd.DataFrame(summary).to_csv(O/'all28_input_checks.tsv',sep='\t',index=False);out=dict(status='ACCEPTED_ALL14_DIALOGUE_CONTEXTS_ALL28_COUNT_ID_PCA_QC_READBACK',observed_UTC=datetime.now(timezone.utc).isoformat(),audit_code_sha256=sha(__file__),input_inventory_sha256=sha(S/'inventory.json'),contexts=14,sides=28,cell_context_records=total,max_logexpr_error=maxdiff,biological_or_MCP_validation=False,checks_sha256=sha(O/'all28_input_checks.tsv'));(O/'inventory.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out))
if __name__=='__main__':main()
